import { useState } from 'react';
import { useSearchParams } from 'react-router-dom';

import { EFilters } from 'features/Filters';
import { EPaginationParams } from 'features/Pagination';
import { useCommonSlice, useSearchParamsWithHash } from 'shared/hooks';
import { EDefaultOptions, EGaCategories, EGaEvents, EGaTypes } from 'shared/typings';
import { sendGaEvent } from 'shared/utils';

export const useStateFilters = (withHash?: boolean) => {
	const [searchParams, setSearchParams] = (withHash ? useSearchParamsWithHash : useSearchParams)();
	const { clearInfinityScroll } = useCommonSlice();

	const [stateSearchParams, setStateSearchParams] = useState<URLSearchParams>(new URLSearchParams(searchParams));

	return {
		applyFilters: () => {
			setSearchParams(stateSearchParams);
		},
		clearFilters: () => {
			const newSearchParams = new URLSearchParams(searchParams);
			for (const key in EFilters) {
				newSearchParams.delete(EFilters[key as keyof typeof EFilters]);
			}

			newSearchParams.delete(EPaginationParams.OFFSET);
			clearInfinityScroll();

			setSearchParams(newSearchParams);
			setStateSearchParams(newSearchParams);
		},
		getFilterValue: (name: EFilters) => {
			return stateSearchParams.get(name) || null;
		},
		getALLFilterValues: (name: EFilters) => {
			return stateSearchParams.getAll(name) || null;
		},
		onFilterChange: (
			field: EFilters,
			value: string | string[] | boolean | null,
			gaOptions?: { event: EGaEvents; option1: EGaCategories },
		) => {
			const newSearchParams = new URLSearchParams(stateSearchParams);

			newSearchParams.delete(field);
			newSearchParams.delete(EPaginationParams.OFFSET);

			if (Array.isArray(value)) {
				value
					.filter((item) => item !== EDefaultOptions.ALL)
					.forEach((item) => {
						item && newSearchParams.append(field, item ? item.toString() : '');
					});
			} else if (value && value !== EDefaultOptions.ALL) {
				newSearchParams.set(field, value.toString());
			}

			setStateSearchParams(newSearchParams);

			gaOptions &&
				sendGaEvent(gaOptions.event, {
					event_option1: gaOptions.option1,
					event_option2: EGaTypes.FILTER,
					event_option4: value?.toString(),
				});
		},
		setInitFiltersFilters: () => {
			setStateSearchParams(searchParams);
		},
	};
};
